  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Alors que de plus en plus de terres fertiles et faciles d’acc&#232;s sont cultiv&#233;es et civilis&#233;es, nombreux sont les druides qui cherchent refuge et solitude dans les sommets &#233;ternels des plus hautes montagnes.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Montagnard (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Montagnard_Ext_0&quot; href=&quot;#Montagnard_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, le personnage re&#231;oit un bonus &#233;gal &#224; la moiti&#233; de son niveau de druide sur ses jets d’&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; et sur ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie), de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; lorsqu’il se trouve en terrain montagneux. Il est &#233;galement impossible de le pister. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pied s&#251;r (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pied_s&#251;r_Ext_1&quot; href=&quot;#Pied_s&#251;r_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, le druide des d&#233;serts ne subit aucune p&#233;nalit&#233; &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse de d&#233;placement&lt;/a&gt; ou sur ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; lorsqu’il marche sur des pentes escarp&#233;es, des &#233;boulis ou des pierres. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Alpiniste (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Alpiniste_Ext_2&quot; href=&quot;#Alpiniste_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le personnage ne perd pas son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; lorsqu’il escalade. Il est immunis&#233; au vertige et n’est pas affect&#233; par les effets du froid naturel, comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sister &#224; l’appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Forme animale (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_animale_Sur_3&quot; href=&quot;#Forme_animale_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un druide des montagnes re&#231;oit cette aptitude au niveau 6 et son niveau effectif sera &#233;gal &#224; son niveau
de druide -2. Il ne peut utiliser ce pouvoir pour adopter une forme v&#233;g&#233;tale. Au niveau 12, il peut se transformer en un g&#233;ant de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; G comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-De-G&#233;ant-I.html&quot; title=&quot;Forme de g&#233;ant I&quot;&gt;forme de g&#233;ant I&lt;/a&gt;&lt;/i&gt;, et au niveau 16 en un g&#233;ant de taille TG comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-De-G&#233;ant-Ii.html&quot; title=&quot;Forme de g&#233;ant II&quot;&gt;forme de g&#233;ant II&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Impassibilit&#233; de la montagne (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Impassibilit&#233;_de_la_montagne_Ext_4&quot; href=&quot;#Impassibilit&#233;_de_la_montagne_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le personnage est immunis&#233; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;P&#233;trification.html&quot; title=&quot;P&#233;trification&quot;&gt;p&#233;trification&lt;/a&gt;. Il re&#231;oit un bonus de +4 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; ou son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; lorsqu’on tente de le &lt;a class=&quot;pagelink&quot; href=&quot;Repousser-(Capacit&#233;).html&quot; title=&quot;Repousser&quot;&gt;pousser&lt;/a&gt;, de le &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Entrainement.html&quot; title=&quot;entra&#238;nement&quot;&gt;tirer&lt;/a&gt;, de le &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charger &#224; mains nues&lt;/a&gt; ou de le tra&#238;ner, ou pour r&#233;sister aux effets qui pourraient le faire bouger de sa position actuelle (&#234;tre la cible de sorts comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;loignement-Du-Bois.html&quot; title=&quot;&#201;loignement du bois&quot;&gt;&#233;loignement du bois&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inversion-De-La-Gravit&#233;.html&quot; title=&quot;Inversion de la gravit&#233;&quot;&gt;inversion de la gravit&#233;&lt;/a&gt;&lt;/i&gt; ou &#234;tre renvers&#233; par des vents violents). Cela ne le prot&#232;ge pas contre les &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;crocs-en-jambe&lt;/a&gt;, ni n’emp&#234;che qu’on l’&lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;agrippe&lt;/a&gt; ou qu’on le &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Renversement.html&quot; title=&quot;renversement&quot;&gt;renverse&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#IMMUNITECONTRELEVENIN&quot; title=&quot;Le druide&quot;&gt;immunit&#233; contre le venin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Granite (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Granite_Ext_5&quot; href=&quot;#Granite_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, un druide des montagnes peut &#224; volont&#233; se transformer en affleurement rocheux, comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Statue.html&quot; title=&quot;Statue&quot;&gt;statue&lt;/a&gt;&lt;/i&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#MILLEVISAGES&quot; title=&quot;Le druide&quot;&gt;mille visages&lt;/a&gt;.
